import{_ as n,o as e,c as s,a2 as i}from"./chunks/framework.EUByU7Iq.js";const b=JSON.parse('{"title":"第五章　股份有限公司的股份发行和转让","description":"","frontmatter":{"title":"第五章　股份有限公司的股份发行和转让","date":"2021-01-05T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"]},"headers":[],"relativePath":"blogs/CL/diwuzhang：gufenyouxiangongsidegufenfaxinghezhuanrang.md","filePath":"blogs/CL/第五章：股份有限公司的股份发行和转让.md"}'),l={name:"blogs/CL/diwuzhang：gufenyouxiangongsidegufenfaxinghezhuanrang.md"};function p(r,a,t,h,o,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<hr><h3 id="第一百二十五条-股份及其形式" tabindex="-1">第一百二十五条 股份及其形式 <a class="header-anchor" href="#第一百二十五条-股份及其形式" aria-label="Permalink to &quot;第一百二十五条 股份及其形式&quot;">​</a></h3><p>股份有限公司的资本划分为股份，每一股的金额相等。 公司的股份采取股票的形式。股票是公司签发的证明股东所持股份的凭证。</p><h3 id="第一百二十六条-股份发行的原则" tabindex="-1">第一百二十六条 股份发行的原则 <a class="header-anchor" href="#第一百二十六条-股份发行的原则" aria-label="Permalink to &quot;第一百二十六条 股份发行的原则&quot;">​</a></h3><p>股份的发行，实行公平、公正的原则，同种类的每一股份应当具有同等权利。 同次发行的同种类股票，每股的发行条件和价格应当相同；任何单位或者个人所认购的股份，每股应当支付相同价额。</p><h3 id="第一百二十七条-股票发行价格" tabindex="-1">第一百二十七条 股票发行价格 <a class="header-anchor" href="#第一百二十七条-股票发行价格" aria-label="Permalink to &quot;第一百二十七条 股票发行价格&quot;">​</a></h3><p>股票发行价格可以按票面金额，也可以超过票面金额，但不得低于票面金额。</p><h3 id="第一百二十八条-股票的形式及载明的事项" tabindex="-1">第一百二十八条 股票的形式及载明的事项 <a class="header-anchor" href="#第一百二十八条-股票的形式及载明的事项" aria-label="Permalink to &quot;第一百二十八条 股票的形式及载明的事项&quot;">​</a></h3><p>股票采用纸面形式或者国务院证券监督管理机构规定的其他形式。 股票应当载明下列主要事项：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）公司名称； </span></span>
<span class="line"><span>（二）公司成立日期； </span></span>
<span class="line"><span>（三）股票种类、票面金额及代表的股份数； </span></span>
<span class="line"><span>（四）股票的编号。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>股票由法定代表人签名，公司盖章。 发起人的股票，应当标明发起人股票字样。</p><h3 id="第一百二十九条-股票的种类" tabindex="-1">第一百二十九条 股票的种类 <a class="header-anchor" href="#第一百二十九条-股票的种类" aria-label="Permalink to &quot;第一百二十九条 股票的种类&quot;">​</a></h3><p>公司发行的股票，可以为记名股票，也可以为无记名股票。 公司向发起人、法人发行的股票，应当为记名股票，并应当记载该发起人、法人的名称或者姓名，不得另立户名或者以代表人姓名记名。</p><h3 id="第一百三十条-股东信息的记载" tabindex="-1">第一百三十条 股东信息的记载 <a class="header-anchor" href="#第一百三十条-股东信息的记载" aria-label="Permalink to &quot;第一百三十条 股东信息的记载&quot;">​</a></h3><p>公司发行记名股票的，应当置备股东名册，记载下列事项：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）股东的姓名或者名称及住所； </span></span>
<span class="line"><span>（二）各股东所持股份数； </span></span>
<span class="line"><span>（三）各股东所持股票的编号； </span></span>
<span class="line"><span>（四）各股东取得股份的日期。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>发行无记名股票的，公司应当记载其股票数量、编号及发行日期。</p><h3 id="第一百三十一条-其他种类的股份" tabindex="-1">第一百三十一条 其他种类的股份 <a class="header-anchor" href="#第一百三十一条-其他种类的股份" aria-label="Permalink to &quot;第一百三十一条 其他种类的股份&quot;">​</a></h3><p>国务院可以对公司发行本法规定以外的其他种类的股份，另行作出规定。</p><h3 id="第一百三十二条-向股东交付股票" tabindex="-1">第一百三十二条 向股东交付股票 <a class="header-anchor" href="#第一百三十二条-向股东交付股票" aria-label="Permalink to &quot;第一百三十二条 向股东交付股票&quot;">​</a></h3><p>股份有限公司成立后，即向股东正式交付股票。公司成立前不得向股东交付股票。</p><h3 id="第一百三十三条-发行新股的决议" tabindex="-1">第一百三十三条 发行新股的决议 <a class="header-anchor" href="#第一百三十三条-发行新股的决议" aria-label="Permalink to &quot;第一百三十三条 发行新股的决议&quot;">​</a></h3><p>公司发行新股，股东大会应当对下列事项作出决议：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）新股种类及数额； </span></span>
<span class="line"><span>（二）新股发行价格； </span></span>
<span class="line"><span>（三）新股发行的起止日期； </span></span>
<span class="line"><span>（四）向原有股东发行新股的种类及数额。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="第一百三十四条-发行新股的程序" tabindex="-1">第一百三十四条 发行新股的程序 <a class="header-anchor" href="#第一百三十四条-发行新股的程序" aria-label="Permalink to &quot;第一百三十四条 发行新股的程序&quot;">​</a></h3><p>公司经国务院证券监督管理机构核准公开发行新股时，必须公告新股招股说明书和财务会计报告，并制作认股书。 本法第八十七条、第八十八条的规定适用于公司公开发行新股。</p><h3 id="第一百三十五条-发行新股的作价方案" tabindex="-1">第一百三十五条 发行新股的作价方案 <a class="header-anchor" href="#第一百三十五条-发行新股的作价方案" aria-label="Permalink to &quot;第一百三十五条 发行新股的作价方案&quot;">​</a></h3><p>公司发行新股，可以根据公司经营情况和财务状况，确定其作价方案。</p><h3 id="第一百三十六条-发行新股的变更登记" tabindex="-1">第一百三十六条 发行新股的变更登记 <a class="header-anchor" href="#第一百三十六条-发行新股的变更登记" aria-label="Permalink to &quot;第一百三十六条 发行新股的变更登记&quot;">​</a></h3><p>公司发行新股募足股款后，必须向公司登记机关办理变更登记，并公告。</p><h3 id="第一百三十七条-股份转让" tabindex="-1">第一百三十七条 股份转让 <a class="header-anchor" href="#第一百三十七条-股份转让" aria-label="Permalink to &quot;第一百三十七条 股份转让&quot;">​</a></h3><p>股东持有的股份可以依法转让。</p><h3 id="第一百三十八条-股份转让的场所" tabindex="-1">第一百三十八条 股份转让的场所 <a class="header-anchor" href="#第一百三十八条-股份转让的场所" aria-label="Permalink to &quot;第一百三十八条 股份转让的场所&quot;">​</a></h3><p>股东转让其股份，应当在依法设立的证券交易场所进行或者按照国务院规定的其他方式进行。</p><h3 id="第一百三十九条-记名股票的转让" tabindex="-1">第一百三十九条 记名股票的转让 <a class="header-anchor" href="#第一百三十九条-记名股票的转让" aria-label="Permalink to &quot;第一百三十九条 记名股票的转让&quot;">​</a></h3><p>记名股票，由股东以背书方式或者法律、行政法规规定的其他方式转让；转让后由公司将受让人的姓名或者名称及住所记载于股东名册。 股东大会召开前二十日内或者公司决定分配股利的基准日前五日内，不得进行前款规定的股东名册的变更登记。但是，法律对上市公司股东名册变更登记另有规定的，从其规定。</p><h3 id="第一百四十条-无记名股票的转让" tabindex="-1">第一百四十条 无记名股票的转让 <a class="header-anchor" href="#第一百四十条-无记名股票的转让" aria-label="Permalink to &quot;第一百四十条 无记名股票的转让&quot;">​</a></h3><p>无记名股票的转让，由股东将该股票交付给受让人后即发生转让的效力。</p><h3 id="第一百四十一条-特定持有人的股份转让" tabindex="-1">第一百四十一条 特定持有人的股份转让 <a class="header-anchor" href="#第一百四十一条-特定持有人的股份转让" aria-label="Permalink to &quot;第一百四十一条 特定持有人的股份转让&quot;">​</a></h3><p>发起人持有的本公司股份，自公司成立之日起一年内不得转让。公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。 公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在任职期间每年转让的股份不得超过其所持有本公司股份总数的百分之二十五；所持本公司股份自公司股票上市交易之日起一年内不得转让。上述人员离职后半年内，不得转让其所持有的本公司股份。公司章程可以对公司董事、监事、高级管理人员转让其所持有的本公司股份作出其他限制性规定。</p><h3 id="第一百四十二条-本公司股份的收购及质押" tabindex="-1">第一百四十二条 本公司股份的收购及质押 <a class="header-anchor" href="#第一百四十二条-本公司股份的收购及质押" aria-label="Permalink to &quot;第一百四十二条 本公司股份的收购及质押&quot;">​</a></h3><p>公司不得收购本公司股份。但是，有下列情形之一的除外：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）减少公司注册资本； </span></span>
<span class="line"><span>（二）与持有本公司股份的其他公司合并； </span></span>
<span class="line"><span>（三）将股份用于员工持股计划或者股权激励； </span></span>
<span class="line"><span>（四）股东因对股东大会作出的公司合并、分立决议持异议，要求公司收购其股份； （五）将股份用于转换上市公司发行的可转换为股票的公司债券； </span></span>
<span class="line"><span>（六）上市公司为维护公司价值及股东权益所必需。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>公司因前款第（一）项、第（二）项规定的情形收购本公司股份的，应当经股东大会决议；公司因前款第（三）项、第（五）项、第（六）项规定的情形收购本公司股份的，可以依照公司章程的规定或者股东大会的授权，经三分之二以上董事出席的董事会会议决议。 公司依照本条第一款规定收购本公司股份后，属于第（一）项情形的，应当自收购之日起十日内注销；属于第（二）项、第（四）项情形的，应当在六个月内转让或者注销；属于第（三）项、第（五）项、第（六）项情形的，公司合计持有的本公司股份数不得超过本公司已发行股份总额的百分之十，并应当在三年内转让或者注销。 上市公司收购本公司股份的，应当依照《中华人民共和国证券法》的规定履行信息披露义务。上市公司因本条第一款第（三）项、第（五）项、第（六）项规定的情形收购本公司股份的，应当通过公开的集中交易方式进行。 公司不得接受本公司的股票作为质押权的标的。</p><h3 id="第一百四十三条-记名股票丢失的救济" tabindex="-1">第一百四十三条 记名股票丢失的救济 <a class="header-anchor" href="#第一百四十三条-记名股票丢失的救济" aria-label="Permalink to &quot;第一百四十三条 记名股票丢失的救济&quot;">​</a></h3><p>记名股票被盗、遗失或者灭失，股东可以依照《中华人民共和国民事诉讼法》规定的公示催告程序，请求人民法院宣告该股票失效。人民法院宣告该股票失效后，股东可以向公司申请补发股票。</p><h3 id="第一百四十四条-上市公司的股票交易" tabindex="-1">第一百四十四条 上市公司的股票交易 <a class="header-anchor" href="#第一百四十四条-上市公司的股票交易" aria-label="Permalink to &quot;第一百四十四条 上市公司的股票交易&quot;">​</a></h3><p>上市公司的股票，依照有关法律、行政法规及证券交易所交易规则上市交易。</p><h3 id="第一百四十五条-上市公司的信息公开" tabindex="-1">第一百四十五条 上市公司的信息公开 <a class="header-anchor" href="#第一百四十五条-上市公司的信息公开" aria-label="Permalink to &quot;第一百四十五条 上市公司的信息公开&quot;">​</a></h3><p>上市公司必须依照法律、行政法规的规定，公开其财务状况、经营情况及重大诉讼，在每会计年度内半年公布一次财务会计报告。</p>`,50)])])}const u=n(l,[["render",p]]);export{b as __pageData,u as default};
